-- Keep generated IDs ready for records added after the seed data.
select setval(pg_get_serial_sequence('public.students', 'student_id'), coalesce((select max(student_id) from public.students), 1), true);
select setval(pg_get_serial_sequence('public.skill_categories', 'category_id'), coalesce((select max(category_id) from public.skill_categories), 1), true);
select setval(pg_get_serial_sequence('public.skills', 'skill_id'), coalesce((select max(skill_id) from public.skills), 1), true);
select setval(pg_get_serial_sequence('public.student_skills', 'student_skill_id'), coalesce((select max(student_skill_id) from public.student_skills), 1), true);
select setval(pg_get_serial_sequence('public.wanted_skills', 'wanted_skill_id'), coalesce((select max(wanted_skill_id) from public.wanted_skills), 1), true);
select setval(pg_get_serial_sequence('public.exchange_requests', 'request_id'), coalesce((select max(request_id) from public.exchange_requests), 1), true);
select setval(pg_get_serial_sequence('public.skill_exchanges', 'exchange_id'), coalesce((select max(exchange_id) from public.skill_exchanges), 1), true);
select setval(pg_get_serial_sequence('public.sessions', 'session_id'), coalesce((select max(session_id) from public.sessions), 1), true);
select setval(pg_get_serial_sequence('public.reviews', 'review_id'), coalesce((select max(review_id) from public.reviews), 1), true);
select setval(pg_get_serial_sequence('public.notifications', 'notification_id'), coalesce((select max(notification_id) from public.notifications), 1), true);
commit;
